ee:variables.ee:set-variable:
%dw 2.0
output application/json
var profile = upper((Mule::p('pagination.profile') default "Bajo") as String)
var maxLimit = if (profile == "ALTO") ((Mule::p('pagination.profiles.alto.max') default 100) as Number) else if (profile == "MEDIO") ((Mule::p('pagination.profiles.medio.max') default 50) as Number) else ((Mule::p('pagination.profiles.bajo.max') default 25) as Number)
var qp = vars.queryParameters default {}
var defaultLimit = maxLimit
var defaultOffset = (Mule::p('pagination.default.offset') default 0) as Number
var reqLimit = (qp.limit default defaultLimit) as Number
var reqOffset = (qp.offset default defaultOffset) as Number
var safeLimit = if (reqLimit > maxLimit) maxLimit else if (reqLimit < 0) 0 else reqLimit
var safeOffset = if (reqOffset < 0) 0 else reqOffset
---
qp ++ {
	limit: safeLimit,
	offset: safeOffset
}

ee:message.ee:set-payload:
%dw 2.0
var normalized = flatten(payload.*payload)
var keyMap = {
	Customer: "customerInfo",
	Products: "productsInfo",
	Notifications: "notificationsInfo",
	Interactions: "interactionsInfo",
	PQRS: "pqrsInfo",
	Billings: "billingsInfo",
	WithHoldings: "withHoldingsInfo",
	Promotions: "promotionsInfo",
	Services: "servicesInfo",
	Orders: "ordersInfo",
	Scheduling: "schedulingInfo"
}
var data = normalized map ((item) -> keyMap filterObject ((newKey, oldKey) -> item[oldKey]?) mapObject ((newKey, oldKey) -> {
	(newKey): item[oldKey]
})) reduce ((item, acc = {
}) -> acc ++ item) default {
}
output application/json
---
{
	status: if ( isEmpty(data) ) 404 else 200,
	code: if ( isEmpty(data) ) "NOT_FOUND" else "OK",
	message: {
		message: if ( isEmpty(data) ) "There is no information available for this query." else "Successful Transaction."
	}
} ++ data

ee:variables.ee:set-variable:
%dw 2.0
output application/json
var normalized = flatten(payload.*payload)
var keyMap = {
	Customer: "customerInfo",
	Products: "productsInfo",
	Notifications: "notificationsInfo",
	Interactions: "interactionsInfo",
	PQRS: "pqrsInfo",
	Billings: "billingsInfo",
	WithHoldings: "withHoldingsInfo",
	Promotions: "promotionsInfo",
	Services: "servicesInfo",
	Orders: "ordersInfo",
	Scheduling: "schedulingInfo"
}
var data =
    normalized map ((item) -> keyMap
                filterObject ((newKey, oldKey) -> item[oldKey]?) mapObject ((newKey, oldKey) -> 
                    {
	(newKey): item[oldKey]
}
                )
)
        reduce ((item, acc = {}) -> acc ++ item)
        default {}
---
if (isEmpty(data)) 404 else 200

